fn compile_with_updates(
    lua: &Lua,
    actors: &[Table],
    states: &[SongLuaOverlayState],
    tracked: &[(SongLuaTrackedActorTarget, Table, SongLuaOverlayState)],
    updates: &[(mlua::Function, usize)],
    reserved: &[usize],
) -> Option<SongLuaCompiledActorInputs> {
