}

pub(crate) fn compile(
    lua: &Lua,
    root: &Value,
    actors: &[Table],
    states: &[SongLuaOverlayState],
    tracked: &[(SongLuaTrackedActorTarget, Table, SongLuaOverlayState)],
) -> Option<SongLuaCompiledActorInteractions> {
