def run(stage,name,trial,prepare=False):
    path=out/f'{name}-{stage}-{trial}{"-prepare" if prepare else ""}.json'
    cmd=[str(out/f'{stage}-timed_input.exe'),str(path)]
    if stage!='baseline':
        cmd += [str(workloads[name])]
        if prepare:cmd+=['prepare']
    with path.with_suffix('.log').open('wb') as log:
        subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT,check=True)
    data=json.loads(path.read_bytes()); templates=[]; indexes={}
    for item in data['trace']:
        state=item['states']
        if state not in indexes:indexes[state]=len(templates);templates.append(state)
        item['states']=indexes[state]
    trace={'steps':data['trace'],'states':templates}
    if name in traces:assert trace==traces[name],(stage,name,trial)
    else:traces[name]=trace
    data['state_templates']=templates
    path.write_text(json.dumps(data,separators=(',',':')))
    records.append(dict(stage=stage,workload=name,trial=trial,prepare_only=prepare,
        report=str(path.relative_to(root)),sha256=sha(path),rows=data['rows'],
        memory=data['retained_memory'],loading_vm_destroyed=data['loading_vm_destroyed']))
